// A stand-in with the shape production-audit intercepts. The real `pg` is not
// a dependency of this package and must not become one; what is under test is
// the interception, not the driver.
class Pool {
  constructor(options) {
    this.options = options;
  }
  async query() {
    return { rows: [] };
  }
  async end() {}
}

class Client {
  constructor(options) {
    this.options = options;
  }
}

module.exports = { Pool, Client };
